import numpy as np
from scipy.optimize import least_squares
def build(w, amp):
    ph=w*np.sqrt(t); c_,s_=np.cos(ph),np.sin(ph)
    base=[np.ones_like(x), x, 1/v, np.log(x), x**3]
    return np.column_stack(base+[amp*c_, amp*s_, c_/v, s_/v])
for name,amp in [("t",t),("sqrt",np.sqrt(t))]:
    best=None
    for w0 in np.linspace(0.2,2.5,24):
        def r(p):
            X=build(p[0],amp); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]; return X@c-dv_dt
        s=least_squares(r,[w0])
        nm=np.mean(s.fun**2)/np.var(dv_dt)
        if best is None or nm<best[0]: best=(nm,s.x[0],s)
    X=build(best[1],amp); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    print(name, best[0], best[1], np.round(c,4))
